"""Val19 storage/representation audit; never reads raw FP-RIR waveforms or Test data."""
import argparse,hashlib,json
from pathlib import Path
import numpy as np

def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
 p=argparse.ArgumentParser();p.add_argument('--workspace',type=Path,required=True);p.add_argument('--root',type=Path,required=True);p.add_argument('--study',type=Path,required=True);p.add_argument('--audit',type=Path,required=True);p.add_argument('--out',type=Path,required=True);a=p.parse_args();audit=json.loads(a.audit.read_text());assert audit['complete'];records=[]
 banks=json.loads((a.study/'banks_v1/manifest.json').read_text());bank_receipts={r['scene']:r for r in banks['records']}
 for r in audit['records']:
  sid=r['scene'];rp=a.root/f'RIR/manifests/dense_banks_v1/verified/val/{sid}.json';receipt=json.loads(rp.read_text());assert receipt['status']=='complete' and receipt['split']=='val' and receipt['scene_id']==sid;assert all(x['path'].startswith(f'RIR/FP/val/{sid}/') for x in receipt['records']);rawbytes=sum(x['bytes'] for x in receipt['records']);assert rawbytes==receipt['raw_bytes']
  folder=a.workspace/r['folder_relative'];fp=np.load(folder/'fp.npy',mmap_mode='r');win=np.load(folder/'windows.npy',mmap_mode='r');xy=np.load(folder/'xy.npy');bp=a.study/'banks_v1'/sid/'grid_20cm.npz';assert sha(bp)==bank_receipts[sid]['files'][bp.name];g=np.load(bp);np.testing.assert_allclose(g['xy'],xy,atol=1e-7,rtol=0)
  fine=a.study/'banks_v1'/sid/'grid_10cm.npz';assert sha(fine)==bank_receipts[sid]['files'][fine.name];gf=np.load(fine)
  records.append(dict(scene=sid,cells20=len(xy),poses20=len(fp),raw_fp_rir_files=receipt['fp_arrays'],raw_fp_rir_bytes_manifest=rawbytes,raw_fp_receipt_sha256=sha(rp),fp_embedding_payload_bytes=fp.nbytes,fp_embedding_file_bytes=(folder/'fp.npy').stat().st_size,visual_windows_payload_bytes=win.nbytes,ray_bank20_payload_bytes=g['world_rays'].nbytes+g['xy'].nbytes,ray_bank20_compressed_file_bytes=bp.stat().st_size,ray_bank10_payload_bytes=gf['world_rays'].nbytes+gf['xy'].nbytes,ray_bank10_compressed_file_bytes=fine.stat().st_size,geometry_both_grids_preparation_seconds=bank_receipts[sid]['seconds']))
 assert len(records)==19;totals={k:sum(r[k] for r in records) for k in records[0] if k not in ['scene','raw_fp_receipt_sha256']};result=dict(scope='Val19 same20cm pose coordinates; physical payload and storage audit, not end-to-end runtime benchmark',records=records,totals=totals,ratios=dict(fp_embedding_payload_over_ray20_payload=totals['fp_embedding_payload_bytes']/totals['ray_bank20_payload_bytes'],raw_fp_storage_over_compressed_ray20=totals['raw_fp_rir_bytes_manifest']/totals['ray_bank20_compressed_file_bytes']),limitations=['Raw FP storage is from existing verified manifests, not fresh per-file stat/hash audit.','FP embeddings represent acoustic simulations; ray profiles represent binary floorplan geometry. Storage ratio is not an information-equivalence or accuracy claim.','Ray banks store36 world directions per XY; candidate yaw uses index rotation. No dense pose-by-ray tensor is saved.','Original FP rendering and feature-extraction wall time not measured here.','Geometry timing covers both20cm and10cm generation together and cannot be called pure20cm latency.','Training, query encoders, B2/GEOQ execution, model weights and common floorplan image storage excluded from these bank figures.','No performance/cost decision until matched accuracy and isolated runtime measurements.'],source_sha256=sha(__file__),input_audit_sha256=sha(a.audit),test_accessed=False,raw_waveforms_read=False)
 a.out.write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(dict(totals=totals,ratios=result['ratios']),indent=2))
if __name__=='__main__':main()
